approaches.css:
/* 2-line clamp on a claim title, not on the why text */
.clamp-2 {
  display: -webkit-box;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
  line-clamp: 2;          /* standardized shorthand; keep the prefixed line above */
  overflow: hidden;
  text-overflow: ellipsis; /* informational; the clamp draws its own ellipsis */
}

/* Hide the toggle when nothing is clamped (JS sets the attribute) */
[data-overflow="false"] > .clamp-2 { -webkit-line-clamp: unset; line-clamp: unset; }
[data-overflow="false"] > .more { display: none; }

/* Overlay variant: fade sits in the bottom padding, never over the last line */
.scroll {
  position: relative;
  overflow-y: auto;
  overscroll-behavior: contain;
}
.scroll::after {
  content: "";
  position: absolute;
  inset-inline: 0;
  bottom: 0;
  height: 2.5rem;
  pointer-events: none;
  background: linear-gradient(
    to bottom,
    color-mix(in srgb, var(--surface) 0%, transparent),
    var(--surface)
  );
  transition: opacity 150ms ease;
}
.scroll[data-at-end="true"]::after { opacity: 0; }
@media (prefers-reduced-motion: reduce) { .scroll::after { transition: none; } }

/* Mask variant: fades the content edge itself. Note it also fades the scrollbar
   and reduces contrast of the final line. */
.scroll--mask {
  mask-image: linear-gradient(to bottom, #000 calc(100% - 2.5rem), transparent);
  -webkit-mask-image: linear-gradient(to bottom, #000 calc(100% - 2.5rem), transparent);
}

/* Shell fills the viewport but never exceeds it */
.detail {
  display: flex;
  flex-direction: column;
  height: 100dvh;              /* fallback: 100vh for older browsers */
  max-height: 100dvh;
  overflow: hidden;
  padding-bottom: env(safe-area-inset-bottom);
}

.detail__header,
.detail__footer { flex: 0 0 auto; }

/* The only scrollable region */
.detail__body {
  flex: 1 1 auto;
  min-height: 0;               /* REQUIRED: lets the flex child shrink and scroll */
  overflow-y: auto;
  overscroll-behavior: contain; /* stop scroll chaining to the page */
  -webkit-overflow-scrolling: touch;
  scrollbar-gutter: stable;
  scroll-padding-block: 1rem;
}

/* Per-claim row: structure survives because each claim is its own element */
.claim {
  display: grid;
  grid-template-columns: 1.25rem 1fr;
  gap: 0.5rem;
  padding-block: 0.75rem;
  border-bottom: 1px solid var(--border);
}
.claim:last-child { border-bottom: 0; }
.claim__text { margin: 0; }

/* Full view: ordinary document scroll, no height clamp */
.article {
  max-width: 65ch;
  margin-inline: auto;
  padding-inline: 1rem;
  padding-block: 1.5rem calc(1.5rem + env(safe-area-inset-bottom));
}
.article h1 { text-wrap: balance; }
.article p  { text-wrap: pretty; }

/* Restore position when returning to the list */
html { scroll-behavior: smooth; }
@media (prefers-reduced-motion: reduce) { html { scroll-behavior: auto; } }

recommendation.css:
/* Detail view: fills the screen, never exceeds it */
.detail {
  display: flex;
  flex-direction: column;
  height: 100dvh;                /* fallback: 100vh */
  max-height: 100dvh;
  overflow: hidden;
  background: var(--surface);
  padding-bottom: env(safe-area-inset-bottom);
}

.detail__header { flex: 0 0 auto; }
.detail__footer { flex: 0 0 auto; }

/* The only scrollable region: fills remaining height */
.detail__body {
  position: relative;
  flex: 1 1 auto;
  min-height: 0;                 /* the critical flex-scroll fix */
  overflow-y: auto;
  overscroll-behavior: contain;  /* no scroll chaining to the page */
  -webkit-overflow-scrolling: touch;
  scrollbar-gutter: stable;
  scroll-padding-block: 1rem;
  padding-inline: 1rem;
}

/* Scroll hint: fade in the bottom padding, not over the last line */
.detail__body::after {
  content: "";
  position: sticky;
  bottom: 0;
  display: block;
  height: 2.5rem;
  margin-top: -2.5rem;
  pointer-events: none;
  background: linear-gradient(
    to bottom,
    color-mix(in srgb, var(--surface) 0%, transparent),
    var(--surface)
  );
  transition: opacity 150ms ease;
}
.detail__body[data-at-end="true"]::after { opacity: 0; }
@media (prefers-reduced-motion: reduce) {
  .detail__body::after { transition: none; }
}

/* Per-claim line: one element per claim keeps the structure */
.claim {
  display: grid;
  grid-template-columns: 1.25rem 1fr;
  gap: 0.5rem;
  padding-block: 0.75rem;
  border-bottom: 1px solid var(--border);
}
.claim:last-child { border-bottom: 0; }
.claim__text { margin: 0; }

/* Escalation control, only shown when the region actually overflows */
.detail__more {
  min-height: 44px;
  min-width: 44px;
}
.detail__more:focus-visible {
  outline: 2px solid var(--focus);
  outline-offset: 2px;
}

/* Optional: summary cards clamp titles only */
.clamp-2 {
  display: -webkit-box;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
  line-clamp: 2;
  overflow: hidden;
}
